# Terza serie «Primo soccorso passo passo» (gennaio-giugno 2027): dieci video, il martedì.
# BOZZA da rivedere (responsabile sanitario): news in bozza e schede nascoste finché non è approvata.
# Fonti (dettaglio in fonti.md): linee guida ERC 2025 (Resuscitation 215, 2025: First Aid 110752, Executive
# Summary 110770) e traduzione IRC 2025 (cap. 4 BLS, 6 Circostanze speciali, 9 PBLS, 12 Primo soccorso);
# IFRC International First Aid Guidelines 2025; IRC/ERC 2021 cap. 8 per dente e occhi (temi tolti da ERC 2025);
# Ministero della Salute (traumi dentali 2018; circolare antitetanica 3/7/2018; linee di indirizzo caldo luglio 2026;
# BIF 2001 vipera); legge 4 agosto 2021, n. 116; ISS (EpiCentro, ISSalute, campagna annegamenti 2025);
# CAV Careggi e Bambino Gesù (occhi); Centro Antiveleni di Milano; Croce Rossa Italiana; Ospedale Pediatrico Bambino Gesù.
# Revisione sanitaria del 1/11/2026 sulle fonti statali più aggiornate (prima gli enti statali, poi ERC/IRC 2025 e IFRC 2025).
from contenuti import S, FINE, U12
SER = 'Primo soccorso passo passo · 3ª serie'
FONTE = "Fonti nell'articolo su misericordia-ariccia.it · informazioni generali, non sostituiscono un corso"
def E(nome, num, scene=None, **kw):
    return dict(nome=nome, num=num, tot=10, serie=SER, scene=scene, fonte=FONTE, voce='luca', effetti=True, **kw)
V5 = {
'dae': E('Il defibrillatore (DAE)', 1, [
  S('Il DAE', ['Il defibrillatore','*salva* la vita.'], 'Il defibrillatore, il di a e: in un arresto cardiaco può far ripartire il cuore. E puoi usarlo anche tu.', 'dae-intro',
    sub='Il defibrillatore, il DAE: in un arresto cardiaco può far ripartire il cuore. E puoi usarlo anche tu.'),
  S('Anche tu', ['Puoi usarlo','*anche tu*.'], 'Anche se non hai fatto un corso, il di a e ti guida con la voce, passo passo. Lo dice la legge centosedici del duemilaventuno: se non c\'è personale formato, anche chi non è formato può usarlo in caso di sospetto arresto cardiaco, senza rischiare di essere punito.', 'dae-voce', [['Anche senza corso', .15], ['Ti guida la voce', .4], ['Legge 116/2021', .85]],
    sub='Anche se non hai fatto un corso, il DAE ti guida con la voce, passo passo. Lo dice la legge 116 del 2021: se non c\'è personale formato, anche chi non è formato può usarlo in caso di sospetto arresto cardiaco, senza rischiare di essere punito.'),
  S('Dove si trova', ['Cerca il','cartello *verde*.'], 'Lo trovi in stazioni, impianti sportivi, uffici pubblici e tanti altri luoghi, segnalato da un cartello verde con un cuore e un fulmine. Se non sai dov\'è, chiedi all\'operatore del '+U12[3:]+': spesso può indicarti il più vicino.', 'cartello-dae', [['Cuore e fulmine', .4], ['Chiedi al 112', .85, 1]],
    sub='Lo trovi in stazioni, impianti sportivi, uffici pubblici e tanti altri luoghi, segnalato da un cartello verde con un cuore e un fulmine. Se non sai dov\'è, chiedi all\'operatore del 112: spesso può indicarti il più vicino.'),
  S('Quando', ['Non risponde,','non *respira*.'], 'Si usa quando una persona non risponde e non respira normalmente. Chiama subito '+U12+' con il vivavoce, inizia le compressioni e fatti portare il di a e.', 'telefono-dae', [['Chiama il 112', .3, 1], ['Compressioni', .6], ['Fatti portare il DAE', .88]],
    sub='Si usa quando una persona non risponde e non respira normalmente. Chiama subito il 112 con il vivavoce, inizia le compressioni e fatti portare il DAE.'),
  S('Accendilo', ['Accendilo e','segui la *voce*.'], 'Appena arriva, aprilo e accendilo: alcuni si accendono da soli quando li apri. Poi fai esattamente quello che ti dice.', 'dae-accendi', [['Apri', .2], ['Accendi', .4], ['Segui la voce', .8]]),
  S('Le piastre', ['Piastre sul','petto *nudo*.'], 'Scopri il torace e attacca le piastre sulla pelle nuda, come nel disegno sulle piastre. Se siete in due, uno continua le compressioni mentre l\'altro le attacca.', 'dae', [['Pelle nuda', .25], ['Come nel disegno', .5], ['In due: non fermarti', .85]]),
  S('L\'analisi', ['Nessuno','lo *tocchi*.'], 'Il di a e analizza il cuore. In questo momento nessuno deve toccare la persona.', 'dae-analisi', [['Analisi', .3], ['Nessuno lo tocchi', .7, 1]],
    sub='Il DAE analizza il cuore. In questo momento nessuno deve toccare la persona.'),
  S('La scarica', ['Se serve,','la *scarica*.'], 'Se serve una scarica, assicurati che nessuno tocchi la persona. Alcuni apparecchi la danno da soli, altri ti chiedono di premere il pulsante.', 'dae-scarica', [['Nessuno lo tocchi', .3, 1], ['Premi se lo chiede', .8]]),
  S('Riprendi', ['Subito di nuovo','*compressioni*.'], 'Dopo la scarica, o se non serve, riprendi subito le compressioni. Di solito, ogni due minuti, il di a e ricontrolla il cuore: continua a seguirlo finché arrivano i soccorsi.', 'dae-rcp', [['Riprendi subito', .25], ['Ogni 2 minuti', .6], ['Fino ai soccorsi', .9]],
    sub='Dopo la scarica, o se non serve, riprendi subito le compressioni. Di solito, ogni 2 minuti, il DAE ricontrolla il cuore: continua a seguirlo finché arrivano i soccorsi.'),
  FINE]),
'pls': E('Posizione laterale di sicurezza', 2, [
  S('Su un fianco', ['Su un fianco,','*respira* meglio.'], 'Posizione laterale di sicurezza: su un fianco le vie del respiro restano aperte, e se vomita, i liquidi escono dalla bocca.', 'pls'),
  S('Quando', ['Non risponde,','ma *respira*.'], 'Se una persona non risponde, chiama subito '+U12+' con il vivavoce e guarda se respira normalmente. Se respira normalmente e non ha avuto un trauma, mettila su un fianco.', 'respiro', [['Chiama il 112', .25, 1], ['Respira normalmente?', .55], ['Niente trauma', .85]],
    sub='Se una persona non risponde, chiama subito il 112 con il vivavoce e guarda se respira normalmente. Se respira normalmente e non ha avuto un trauma, mettila su un fianco.'),
  S('1 · Il braccio', ['Il braccio','ad *angolo retto*.'], 'Inginocchiati al suo fianco e controlla che abbia le gambe distese. Metti il suo braccio più vicino a te ad angolo retto rispetto al corpo.', 'pls-1', [['Gambe distese', .2], ['Braccio ad angolo retto', .7]]),
  S('2 · La mano', ['La mano sotto','la *guancia*.'], 'Porta l\'altro braccio sul petto e appoggia il dorso della sua mano sulla guancia rivolta verso di te. Tienila lì.', 'pls-2', [['Braccio sul petto', .3], ['Dorso sulla guancia', .75]]),
  S('3 · Il ginocchio', ['Piega','il *ginocchio*.'], 'Con l\'altra mano afferra la gamba lontana, appena sopra il ginocchio, e sollevala piegandola, con il piede a terra.', 'pls-3', [['Sopra il ginocchio', .3], ['Piede a terra', .75]]),
  S('4 · Giralo', ['Giralo','verso di *te*.'], 'Tenendo la mano premuta sulla guancia, tira la gamba piegata e fallo rotolare con delicatezza verso di te. Sistema la gamba di sopra con anca e ginocchio ad angolo retto.', 'pls-4', [['Tira la gamba', .25], ['Verso di te', .5], ['Anca e ginocchio a 90°', .85]]),
  S('5 · La testa', ['Testa indietro,','*bocca* in giù.'], 'Inclina con delicatezza la testa all\'indietro, per tenere aperte le vie del respiro. Sistema la mano sotto la guancia, così la bocca resta rivolta verso il basso.', 'pls', [['Testa indietro', .3], ['Bocca verso il basso', .8]]),
  S('Controlla', ['Controlla','il *respiro*.'], 'Resta con lui e controlla spesso che respiri normalmente. Lascialo solo soltanto se devi andare a chiamare aiuto. Se smette di respirare normalmente, mettilo a pancia in su e inizia la rianimazione.', 'rcp-mini', [['Controlla spesso', .2], ['Solo per chiamare aiuto', .5], ['Non respira: rianimazione', .9]]),
  S('Attenzione', ['Dopo un trauma,','*non* girarlo.'], 'Se ha avuto un trauma, come una caduta dall\'alto o un incidente, non metterlo su un fianco: non muoverlo e segui l\'operatore del '+U12[3:]+'.', 'non-muovere', [['Caduta o incidente', .3], ['Non muoverlo', .6], ['Segui l\'operatore', .85]],
    sub='Se ha avuto un trauma, come una caduta dall\'alto o un incidente, non metterlo su un fianco: non muoverlo e segui l\'operatore del 112.'),
  FINE]),
'sangue-naso': E('Sangue dal naso', 3, [
  S('Sangue dal naso', ['Testa in','*avanti*.'], 'Sangue dal naso: fa impressione, ma quasi sempre basta stringere il naso nel modo giusto.', 'naso'),
  S('Seduto', ['Seduto,','testa in *avanti*.'], 'Fallo sedere con la testa leggermente in avanti. Così il sangue esce dal naso e non va in gola.', 'naso-avanti', [['Seduto', .2], ['Testa in avanti', .6]]),
  S('Mai indietro', ['Mai la testa','*indietro*.'], 'Non piegare la testa all\'indietro e non farlo sdraiare: il sangue andrebbe in gola e nello stomaco, e può fargli venire nausea e vomito.', 'naso-no-indietro', [['Niente testa indietro', .3], ['Non sdraiarlo', .7]]),
  S('Stringi', ['Stringi la parte','*morbida*.'], 'Stringi con pollice e indice la parte morbida del naso, sotto l\'osso, chiudendo le narici. Respira con la bocca e sputa il sangue.', 'naso-stringi', [['Pollice e indice', .2], ['Parte morbida', .45], ['Respira con la bocca', .8]]),
  S('Il tempo', ['Per 10-15','*minuti*.'], 'Tieni stretto per dieci, quindici minuti di fila, senza mollare per controllare.', 'timer15', [['10-15 minuti', .4], ['Non mollare', .8]],
    sub='Tieni stretto per 10-15 minuti di fila, senza mollare per controllare.'),
  S('Niente nel naso', ['Niente','nel *naso*.'], 'Non infilare cotone, garze o fazzoletti nel naso.', 'naso-no-cotone', [['Niente cotone', .3], ['Niente garze', .6]]),
  S('Non si ferma?', ['Non si ferma?','*Riprova*.'], 'Se continua, stringi di nuovo per altri dieci, quindici minuti. Se anche dopo il secondo tentativo sanguina, vai subito dal medico o al pronto soccorso.', 'medico', [['Altri 10-15 minuti', .3], ['Poi: medico o PS', .8]],
    sub='Se continua, stringi di nuovo per altri 10-15 minuti. Se anche dopo il secondo tentativo sanguina, vai subito dal medico o al pronto soccorso.'),
  S('Quando chiamare', ['Chiama','il *112*.'], 'Chiama '+U12+' se perde molto sangue, se è pallido, sudato o si sente svenire, se è successo dopo un colpo alla testa e ha mal di testa forte, vomita o è confuso, o se prende farmaci anticoagulanti e il sangue non si ferma.', 'telefono', [['Tanto sangue', .15], ['Pallido o debole', .35], ['Colpo alla testa', .6], ['Anticoagulanti', .85]],
    sub='Chiama il 112 se perde molto sangue, se è pallido, sudato o si sente svenire, se è successo dopo un colpo alla testa e ha mal di testa forte, vomita o è confuso, o se prende farmaci anticoagulanti e il sangue non si ferma.'),
  S('Nelle ore dopo', ['Il giorno','*dopo*.'], 'Quando si ferma, per un giorno non soffiare il naso con forza, evita gli sforzi e le bevande calde.', 'naso-dopo', [['Naso: niente forza', .3], ['Niente sforzi', .55], ['Niente bevande calde', .85]]),
  FINE]),
'ferite': E('Ferite e tagli', 4, [
  S('Ferite', ['Pulisci','e *copri*.'], 'Tagli e sbucciature: per guarire bene, vanno puliti e coperti.', 'ferita'),
  S('Le mani', ['Prima,','le *mani*.'], 'Prima lavati le mani con acqua e sapone e, se li hai, indossa i guanti.', 'guanti', [['Acqua e sapone', .3], ['Guanti', .75]]),
  S('Se sanguina', ['Premi con','una *garza*.'], 'Se sanguina, premi con una garza pulita finché il sangue si ferma. Se ne esce tanto, chiama '+U12+' e continua a premere forte.', 'premi', [['Garza pulita', .3], ['Tanto sangue: 112', .8, 1]],
    sub='Se sanguina, premi con una garza pulita finché il sangue si ferma. Se ne esce tanto, chiama il 112 e continua a premere forte.'),
  S('Lava', ['Sotto l\'acqua','*corrente*.'], 'Lava la ferita sotto l\'acqua corrente pulita, anche quella del rubinetto, per togliere lo sporco.', 'rubinetto', [['Acqua del rubinetto', .4], ['Via lo sporco', .8]]),
  S('Disinfetta', ['Disinfettante','*senza* alcol.'], 'Se vuoi disinfettare, usa un disinfettante senza alcol. Niente alcol, che brucia e rallenta la guarigione, e niente cotone, che lascia fili nella ferita.', 'disinfetta', [['Senza alcol', .3], ['Niente cotone', .75]]),
  S('Copri', ['Cerotto','o *garza*.'], 'Asciuga la pelle intorno e copri la ferita con un cerotto o una garza. Cambiali se si sporcano o si bagnano.', 'cerotto', [['Asciuga intorno', .25], ['Cerotto o garza', .55], ['Cambia se sporco', .85]]),
  S('Pronto soccorso', ['Quando serve','il *medico*.'], 'Vai al pronto soccorso se il sangue non si ferma, se la ferita è profonda o ha i bordi aperti, se dentro c\'è qualcosa di conficcato, o se è sul viso. Fatti vedere da un medico per i morsi di animali.', 'trasporti', [['Non si ferma', .15], ['Profonda o aperta', .35], ['Oggetto conficcato', .55], ['Viso', .7], ['Morsi', .9]]),
  S('Antitetanica', ['Antitetanica','*in regola*?'], 'Se la ferita è profonda, sporca di terra o è un morso, e l\'ultimo richiamo dell\'antitetanica è di più di cinque anni fa, o non lo ricordi, vai dal tuo medico o al pronto soccorso, il prima possibile.', 'antitetanica', [['Profonda, sporca o morso', .25], ['Richiamo oltre 5 anni', .6], ['Non lo ricordi?', .85]],
    sub='Se la ferita è profonda, sporca di terra o è un morso, e l\'ultimo richiamo dell\'antitetanica è di più di 5 anni fa, o non lo ricordi, vai dal tuo medico o al pronto soccorso, il prima possibile.'),
  S('Infezione', ['Rossa e calda?','*Dal medico*.'], 'Nei giorni dopo, se la pelle intorno diventa rossa, calda e fa sempre più male, se esce pus o viene la febbre, fatti vedere dal medico.', 'ferita-infetta', [['Rossa e calda', .25], ['Pus', .55], ['Febbre', .8]]),
  FINE]),
'dente': E('Dente caduto o rotto', 5, [
  S('Dente', ['Dente caduto?','*Non perderlo*.'], 'Un dente che cade per un colpo, a volte, si può salvare. Ma bisogna fare in fretta.', 'dente'),
  S('Il sangue', ['Una garza','da *mordere*.'], 'Per fermare il sangue, premi una garza pulita sul punto da cui è uscito il dente, o fagliela mordere. Non farla mordere ai bambini piccoli o a chi non è ben sveglio: potrebbe ingoiarla.', 'dente-garza', [['Garza pulita', .25], ['Da mordere', .5], ['Non ai più piccoli', .85]]),
  S('Da latte?', ['Da latte','o *definitivo*?'], 'Un dente da latte non va rimesso a posto: fallo vedere comunque dal dentista. Un dente definitivo, invece, lo rimette a posto il dentista, e ogni minuto conta.', 'denti-latte', [['Da latte: dal dentista', .35], ['Definitivo: in fretta', .85]]),
  S('Prendilo bene', ['Dalla','*corona*.'], 'Raccogli il dente prendendolo dalla parte bianca, la corona. Non toccare la radice e non strofinarlo.', 'dente-corona', [['La parte bianca', .3], ['Non la radice', .6], ['Non strofinarlo', .85]]),
  S('Conservalo', ['Nel','*latte*.'], 'Mettilo subito in un bicchiere di latte. Se non c\'è, va bene la soluzione fisiologica, quella delle fialette della cassetta di primo soccorso. Non lasciarlo all\'asciutto e non metterlo nell\'acqua del rubinetto.', 'dente-latte', [['Latte', .2], ['Fisiologica', .5], ['Niente acqua del rubinetto', .82]]),
  S('Se non hai altro', ['Se non hai','*nient\'altro*.'], 'Se non hai altro, mettilo in un piccolo contenitore con un po\' della sua saliva. Non farlo tenere in bocca, soprattutto ai bambini: potrebbero ingoiarlo.', 'dente-saliva', [['Un po\' di saliva', .3], ['Non in bocca', .75]]),
  S('Dal dentista', ['Subito dal','*dentista*.'], 'Vai subito dal dentista o al pronto soccorso, e porta il dente con te. Un dente definitivo rimesso in fretta da un professionista spesso si salva.', 'trasporti', [['Dentista o PS', .3], ['Porta il dente', .7]]),
  S('Dente rotto', ['Si è','*scheggiato*?'], 'Se il dente si è solo rotto, cerca il pezzo, conservalo nel latte o nella fisiologica e vai subito dal dentista.', 'dente-rotto', [['Cerca il pezzo', .3], ['Latte o fisiologica', .55], ['Subito dal dentista', .85]]),
  S('Attenzione', ['Ha battuto','la *testa*?'], 'Se ha battuto forte la testa, se è confuso, vomita o ha perso conoscenza, chiama subito '+U12+': prima viene la persona, poi il dente.', 'telefono', [['Confuso o vomita', .3], ['Chiama il 112', .7, 1]],
    sub='Se ha battuto forte la testa, se è confuso, vomita o ha perso conoscenza, chiama subito il 112: prima viene la persona, poi il dente.'),
  FINE]),
'occhi-chimici': E('Sostanze chimiche negli occhi', 6, [
  S('Occhi', ['Prodotti','negli *occhi*.'], 'Detersivi, candeggina e altri prodotti chimici negli occhi o sulla pelle: la prima cosa è l\'acqua, subito.', 'occhio-chimico'),
  S('Acqua subito', ['Acqua,','*subito*.'], 'Sciacqua subito l\'occhio con acqua corrente pulita, tenendo le palpebre aperte. Non perdere tempo a cercare altro.', 'occhi', [['Acqua corrente', .3], ['Palpebre aperte', .7]]),
  S('A lungo', ['Sciacqua','*a lungo*.'], 'Continua per almeno quindici minuti, senza fermarti. Fai attenzione a non far colare l\'acqua nell\'altro occhio.', 'occhi-timer', [['Almeno 15 minuti', .35], ['Salva l\'altro occhio', .8]],
    sub='Continua per almeno 15 minuti, senza fermarti. Fai attenzione a non far colare l\'acqua nell\'altro occhio.'),
  S('Le lenti', ['Via le','*lenti*.'], 'Se porta le lenti a contatto, toglile se ci riesci facilmente, e continua a sciacquare.', 'lenti', [['Togli le lenti', .4], ['Continua a sciacquare', .8]]),
  S('Solo acqua', ['Niente','*colliri*.'], 'Non mettere colliri o altri prodotti: solo acqua, poi decidono i sanitari.', 'no-collirio', [['Niente colliri', .3], ['Solo acqua', .7]]),
  S('Chiama', ['112 o','*Antiveleni*.'], 'Mentre sciacqui, fai chiamare '+U12+' o un Centro Antiveleni, e tieni a portata di mano la confezione del prodotto. A Roma rispondono giorno e notte il Gemelli, l\'Umberto primo e, per i bambini, il Bambino Gesù.', 'cav', [['Chiama il 112', .2, 1], ['Centro Antiveleni', .45], ['La confezione', .85]],
    sub='Mentre sciacqui, fai chiamare il 112 o un Centro Antiveleni, e tieni a portata di mano la confezione del prodotto. A Roma rispondono giorno e notte il Gemelli, l\'Umberto I e, per i bambini, il Bambino Gesù.'),
  S('Pronto soccorso', ['Non guidare','*da solo*.'], 'L\'occhio deve vederlo un medico, al pronto soccorso. Chi è stato colpito non deve guidare: fallo accompagnare.', 'trasporti', [['Pronto soccorso', .35], ['Non guidare', .75]]),
  S('Sulla pelle', ['Via i vestiti,','*tanta acqua*.'], 'Sulla pelle: togli subito i vestiti contaminati, con i guanti se li hai, e lava con tanta acqua corrente.', 'rubinetto', [['Via i vestiti', .25], ['Guanti', .5], ['Tanta acqua', .8]]),
  S('Previeni', ['Guanti','e *occhiali*.'], 'Per prevenire: guanti e occhiali quando usi prodotti aggressivi, e prodotti sempre chiusi, nella confezione originale, lontano dai bambini.', 'protezioni', [['Guanti', .2], ['Occhiali', .35], ['Confezione originale', .7]]),
  FINE]),
'zecche': E('Zecche', 7, [
  S('Zecche', ['Toglila','*subito*.'], 'Zecche: vivono nell\'erba alta e tra i cespugli, e in primavera e in estate è più facile trovarle.', 'zecca'),
  S('Previeni', ['Abiti chiari,','*pantaloni lunghi*.'], 'Nelle passeggiate nel verde: abiti chiari, così le vedi meglio, pantaloni lunghi e un repellente adatto anche alle zecche. Non camminare nell\'erba alta.', 'zecca-vestiti', [['Abiti chiari', .2], ['Pantaloni lunghi', .4], ['Repellente', .65], ['Niente erba alta', .9]]),
  S('Controlla', ['Al rientro,','*controlla*.'], 'Al rientro controlla bene la pelle, soprattutto testa, collo, dietro le ginocchia e i fianchi, e scuoti i vestiti prima di entrare in casa. Controlla anche il cane.', 'zecca-controllo', [['Testa e collo', .2], ['Dietro le ginocchia', .45], ['Scuoti i vestiti', .7], ['Anche il cane', .9]]),
  S('La pinzetta', ['Pinzetta','a *punte sottili*.'], 'Se ne trovi una, toglila il prima possibile, con i guanti se li hai. Usa una pinzetta a punte sottili, o l\'apposito strumento, e afferrala il più vicino possibile alla pelle.', 'zecca-pinzetta', [['Il prima possibile', .2], ['Punte sottili', .5], ['Vicino alla pelle', .85]]),
  S('Tira piano', ['Tira','*piano*.'], 'Tira dolcemente, senza strappi e senza schiacciarla.', 'zecca-tira', [['Dolcemente', .3], ['Senza strappi', .55], ['Non schiacciarla', .85]]),
  S('Mai', ['Niente olio,','*niente fuoco*.'], 'Non metterci mai alcol, olio, benzina, acetone o altri prodotti, e non bruciarla.', 'zecca-no', [['Niente alcol', .15], ['Niente olio', .35], ['Niente benzina', .55], ['Niente fuoco', .85]]),
  S('Dopo', ['Lava','e *disinfetta*.'], 'Poi lava con acqua e sapone e disinfetta, con un disinfettante che non colora la pelle, e lavati le mani. Se resta un pezzetto nella pelle, fatti vedere dal medico.', 'zecca-dopo', [['Acqua e sapone', .2], ['Disinfettante incolore', .5], ['Resta un pezzo? Medico', .85]]),
  S('Segna la data', ['Segna','la *data*.'], 'Segna sul calendario il giorno e il luogo del morso e, per un mese, tieni d\'occhio il punto e come ti senti.', 'calendario', [['Data e luogo', .35], ['Per un mese', .8]]),
  S('Dal medico', ['Alone rosso?','*Dal medico*.'], 'Vai dal medico se compare un alone rosso che si allarga, o se vengono febbre, mal di testa, debolezza, dolori alle articolazioni o ghiandole gonfie. Antibiotici solo se li prescrive lui, non per precauzione.', 'zecca-alone', [['Alone che si allarga', .2], ['Febbre', .4], ['Dolori', .6], ['Antibiotici: no da solo', .9]]),
  FINE]),
'vipera': E('Morso di vipera', 8, [
  S('Vipera', ['Calma,','e *fermo*.'], 'Morso di vipera: in Italia è l\'unico serpente velenoso. Ecco cosa fare, e soprattutto cosa non fare.', 'vipera'),
  S('Riconosci', ['Due puntini,','*dolore*.'], 'Di solito si vedono due puntini vicini, a volte uno solo. Poi dolore forte, gonfiore e un livido intorno.', 'morso-vipera', [['Due puntini', .2], ['Dolore', .45], ['Gonfiore', .65], ['Livido', .85]]),
  S('Chiama', ['Chiama','il *112*.'], 'Chiama subito '+U12+' e di\' che è stato un morso di serpente. Anche se sembra stare bene, deve essere visto in ospedale.', 'telefono', [['Chiama il 112', .3, 1], ['Morso di serpente', .6], ['Sempre in ospedale', .88]],
    sub='Chiama subito il 112 e di\' che è stato un morso di serpente. Anche se sembra stare bene, deve essere visto in ospedale.'),
  S('Fermo', ['Sdraiato','e *fermo*.'], 'Fallo sdraiare, calmo, e che si muova il meno possibile. Non deve camminare: muoversi aiuta il veleno a diffondersi.', 'vipera-fermo', [['Sdraiato', .2], ['Calmo', .4], ['Non camminare', .8]]),
  S('L\'arto', ['L\'arto','*fermo*.'], 'Tieni fermo l\'arto morso, come se fosse rotto: il braccio in una fascia, la gamba ben sostenuta.', 'fascia', [['Come se fosse rotto', .4], ['Braccio nella fascia', .8]]),
  S('Anelli', ['Via anelli','e *orologio*.'], 'Togli subito anelli, orologio e vestiti stretti dall\'arto morso, prima che si gonfi.', 'anelli', [['Anelli', .2], ['Orologio', .45], ['Vestiti stretti', .75]]),
  S('Cosa non fare', ['Niente laccio,','niente *tagli*.'], 'Non stringere lacci o bende, non tagliare e non succhiare il veleno. Niente ghiaccio e niente caldo.', 'vipera-no', [['Niente laccio', .15], ['Niente tagli', .35], ['Non succhiare', .55], ['Niente ghiaccio', .8]]),
  S('Il siero', ['Il siero,','*solo* in ospedale.'], 'Il siero antivipera si usa solo in ospedale, e solo se il medico decide che serve.', 'siero', [['Solo in ospedale', .5]]),
  S('Previeni', ['Scarponi','e *attenzione*.'], 'La vipera morde solo se si sente disturbata. Sui sentieri usa scarponcini e pantaloni lunghi, non sederti sui muretti al sole e non infilare le mani tra sassi e cespugli.', 'sentiero', [['Scarponcini', .25], ['Pantaloni lunghi', .45], ['Niente muretti al sole', .7], ['Mani fuori dai cespugli', .9]]),
  FINE]),
'colpo-calore': E('Colpo di calore', 9, [
  S('Colpo di calore', ['Raffredda,','*subito*.'], 'Colpo di calore: è una vera emergenza, soprattutto per anziani, bambini e chi fa sforzi sotto il sole. La cosa che salva è raffreddare il corpo, subito.', 'termometro-caldo'),
  S('I segni', ['Caldo','e *confuso*.'], 'Pelle molto calda, mal di testa, nausea. Poi confusione, agitazione, discorsi strani, fino a convulsioni o perdita di coscienza.', 'caldo-segni', [['Pelle calda', .15], ['Confusione', .5], ['Convulsioni', .75], ['Non risponde', .9]]),
  S('Chiama', ['Chiama','il *112*.'], 'Chiama subito '+U12+'. E intanto non aspettare: inizia a raffreddarlo.', 'telefono', [['Chiama il 112', .3, 1], ['E intanto raffredda', .8]],
    sub='Chiama subito il 112. E intanto non aspettare: inizia a raffreddarlo.'),
  S('Al fresco', ['Via dal','*caldo*.'], 'Portalo all\'ombra o in un posto fresco, e togligli più vestiti possibile. Se ha le vertigini fallo stare sdraiato; se ha nausea, mettilo su un fianco.', 'ombra', [['All\'ombra', .2], ['Via i vestiti', .45], ['Vertigini: sdraiato', .7], ['Nausea: su un fianco', .9]]),
  S('Bagna e fai aria', ['Bagnalo','e fagli *aria*.'], 'Bagnagli tutto il corpo con acqua fresca, o avvolgilo in teli bagnati, e fagli aria di continuo, con un ventaglio o un ventilatore: l\'acqua che evapora lo raffredda.', 'raffredda', [['Acqua fresca', .25], ['Teli bagnati', .5], ['Aria di continuo', .85]]),
  S('Ancora', ['Bagna','*di nuovo*.'], 'Quando i teli si asciugano, bagnali di nuovo, e sposta spesso l\'aria da una parte all\'altra del corpo.', 'raffredda', [['Bagna di nuovo', .35], ['Sposta l\'aria', .8]]),
  S('Non fermarti', ['Prima','*raffredda*.'], 'Continua a raffreddarlo e segui l\'operatore del '+U12[3:]+'. Da bere solo se è ben sveglio, non ha nausea e riesce a bere, a piccoli sorsi. Niente farmaci per la febbre e niente alcol sulla pelle.', 'raffredda', [['Segui l\'operatore', .2], ['Sorsi, se sveglio', .5], ['Niente antifebbre', .75], ['Niente alcol', .9]],
    sub='Continua a raffreddarlo e segui l\'operatore del 112. Da bere solo se è ben sveglio, non ha nausea e riesce a bere, a piccoli sorsi. Niente farmaci per la febbre e niente alcol sulla pelle.'),
  S('Se non risponde', ['Pronto alla','*rianimazione*.'], 'Se non risponde e non respira normalmente, inizia la rianimazione, con l\'operatore del '+U12[3:]+' al telefono.', 'rcp-mini', [['Rianimazione', .5], ['Operatore al telefono', .85, 1]],
    sub='Se non risponde e non respira normalmente, inizia la rianimazione, con l\'operatore del 112 al telefono.'),
  S('Previeni', ['Ore fresche,','*acqua*, ombra.'], 'Per prevenire: esci nelle ore più fresche, bevi anche senza sete e telefona agli anziani soli. Mai nessuno chiuso in auto al sole, nemmeno per pochi minuti.', 'caldo-previeni', [['Ore fresche', .15], ['Bevi', .35], ['Anziani soli', .6], ['Mai in auto', .9]]),
  FINE]),
'annegamento': E('Annegamento', 10, [
  S('Annegamento', ['In acqua,','*occhi aperti*.'], 'Annegamento: succede in fretta, e spesso in silenzio. Chi sta annegando a volte non riesce a chiamare aiuto né a sbracciarsi.', 'annega'),
  S('Resta a terra', ['Non entrare','in *acqua*.'], 'Se non sei addestrato al salvataggio, non entrare in acqua: rischi di annegare anche tu. Chiama aiuto e fai chiamare '+U12+'.', 'riva', [['Resta a terra', .3], ['Chiama aiuto', .55], ['112', .85, 1]],
    sub='Se non sei addestrato al salvataggio, non entrare in acqua: rischi di annegare anche tu. Chiama aiuto e fai chiamare il 112.'),
  S('Lancia', ['Lancia qualcosa','che *galleggia*.'], 'Da terra, lanciagli un salvagente o qualcosa che galleggia, oppure tendigli un\'asta o una corda.', 'salvagente', [['Salvagente', .25], ['Qualcosa che galleggia', .55], ['Asta o corda', .85]]),
  S('Fuori dall\'acqua', ['Risponde?','*Respira*?'], 'Quando è fuori dall\'acqua, chiamalo e guarda se respira normalmente.', 'respiro', [['Risponde?', .3], ['Respira normalmente?', .7]]),
  S('Rianima', ['Non respira?','*Rianima* subito.'], 'Se non risponde e non respira normalmente, chiama '+U12+' con il vivavoce e inizia subito la rianimazione. Se non hai fatto un corso, fai le compressioni, senza fermarti.', 'rcp-mini', [['Vivavoce', .2, 1], ['Rianima subito', .5], ['Senza corso: compressioni', .85]],
    sub='Se non risponde e non respira normalmente, chiama il 112 con il vivavoce e inizia subito la rianimazione. Se non hai fatto un corso, fai le compressioni, senza fermarti.'),
  S('Se sei formato', ['Formato?','Prima *5 soffi*.'], 'Se sei formato, comincia con cinque soffi, perché nell\'annegamento manca prima di tutto l\'ossigeno. Poi trenta compressioni e due soffi.', 'ventila5', [['5 soffi', .3], ['Manca l\'ossigeno', .6], ['Poi 30 e 2', .9]],
    sub='Se sei formato, comincia con 5 soffi, perché nell\'annegamento manca prima di tutto l\'ossigeno. Poi 30 compressioni e 2 soffi.'),
  S('Il DAE', ['Asciuga','il *torace*.'], 'Se arriva il di a e, asciuga il torace prima di attaccare le piastre, e segui la sua voce.', 'dae', [['Asciuga', .35], ['Piastre', .6], ['Segui la voce', .85]],
    sub='Se arriva il DAE, asciuga il torace prima di attaccare le piastre, e segui la sua voce.'),
  S('Se vomita', ['Se vomita,','*sul fianco*.'], 'Spesso chi è stato in acqua vomita: giralo su un fianco per liberare la bocca, poi riprendi. Se respira, lascialo su un fianco, coprilo e tienilo al caldo.', 'pls', [['Su un fianco', .3], ['Coprilo', .7]]),
  S('Previeni', ['Bambini','*sempre vicini*.'], 'Per prevenire: tieni sempre d\'occhio i bambini vicino all\'acqua, da vicino. Fai il bagno dove c\'è il bagnino e mai da solo, niente alcol prima di entrare in acqua, e fai imparare a nuotare ai bambini.', 'acqua-sicura', [['Bambini sempre vicini', .2], ['Dove c\'è il bagnino', .45], ['Niente alcol', .7], ['Impara a nuotare', .9]]),
  FINE]),
}
